#include <stdint.h>
#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>
void *allocate_array(size_t count, size_t element_size) {
 if (element_size != 0 && count > SIZE_MAX / element_size) return NULL;
 return malloc(count * element_size);
}
int main(void) {
 int *items = allocate_array(10, sizeof *items);
 free(items);
 return 0;
}
